-- ADVANCED BANKING TRANSACTION, FRAUD DETECTION & RISK ANALYTICS
-- MySQL 8.0+
-- Dataset: 100,000 customers | 150,000 accounts | 1,000,000 transactions
--          500,000 card transactions | 50,000 loans | 500,000 loan payments
--          20,000 merchants | 50,000 fraud alerts | 100 branches
-- Generated for portfolio/interview practice.
DROP DATABASE IF EXISTS banking_fraud_analytics;
CREATE DATABASE banking_fraud_analytics;
USE banking_fraud_analytics;
SET FOREIGN_KEY_CHECKS=0;



CREATE TABLE branches (
 branch_id INT PRIMARY KEY,
 branch_name VARCHAR(120) NOT NULL,
 city VARCHAR(80) NOT NULL,
 state VARCHAR(80) NOT NULL,
 opening_date DATE NOT NULL
);

CREATE TABLE employees (
 employee_id INT PRIMARY KEY,
 branch_id INT NOT NULL,
 employee_name VARCHAR(150) NOT NULL,
 role VARCHAR(80) NOT NULL,
 hire_date DATE NOT NULL,
 salary DECIMAL(12,2) NOT NULL,
 FOREIGN KEY (branch_id) REFERENCES branches(branch_id)
);

CREATE TABLE customers (
 customer_id INT PRIMARY KEY,
 first_name VARCHAR(80) NOT NULL,
 last_name VARCHAR(80) NOT NULL,
 email VARCHAR(160) NOT NULL UNIQUE,
 phone VARCHAR(20) NOT NULL,
 date_of_birth DATE NOT NULL,
 city VARCHAR(80) NOT NULL,
 state VARCHAR(80) NOT NULL,
 occupation VARCHAR(100),
 annual_income DECIMAL(14,2) NOT NULL,
 customer_since DATE NOT NULL,
 risk_category ENUM('Low','Medium','High') NOT NULL
);

CREATE TABLE accounts (
 account_id BIGINT PRIMARY KEY,
 customer_id INT NOT NULL,
 branch_id INT NOT NULL,
 account_type ENUM('Savings','Current','Salary','Business') NOT NULL,
 opened_date DATE NOT NULL,
 current_balance DECIMAL(16,2) NOT NULL,
 status ENUM('Active','Dormant','Closed','Frozen') NOT NULL,
 FOREIGN KEY (customer_id) REFERENCES customers(customer_id),
 FOREIGN KEY (branch_id) REFERENCES branches(branch_id)
);

CREATE TABLE merchants (
 merchant_id INT PRIMARY KEY,
 merchant_name VARCHAR(160) NOT NULL,
 merchant_category VARCHAR(100) NOT NULL,
 city VARCHAR(80) NOT NULL,
 state VARCHAR(80) NOT NULL,
 risk_level ENUM('Low','Medium','High') NOT NULL
);

CREATE TABLE beneficiaries (
 beneficiary_id INT PRIMARY KEY,
 customer_id INT NOT NULL,
 beneficiary_name VARCHAR(150) NOT NULL,
 bank_name VARCHAR(120) NOT NULL,
 city VARCHAR(80) NOT NULL,
 created_date DATE NOT NULL,
 FOREIGN KEY (customer_id) REFERENCES customers(customer_id)
);

CREATE TABLE transactions (
 transaction_id BIGINT PRIMARY KEY,
 account_id BIGINT NOT NULL,
 merchant_id INT NULL,
 transaction_time DATETIME NOT NULL,
 transaction_type ENUM('Deposit','Withdrawal','Transfer','Payment','Refund','Fee') NOT NULL,
 amount DECIMAL(14,2) NOT NULL,
 channel ENUM('ATM','Branch','UPI','Online','POS','Mobile') NOT NULL,
 city VARCHAR(80) NOT NULL,
 state VARCHAR(80) NOT NULL,
 status ENUM('Success','Failed','Pending','Reversed') NOT NULL,
 reference_code VARCHAR(40) NOT NULL,
 FOREIGN KEY (account_id) REFERENCES accounts(account_id),
 FOREIGN KEY (merchant_id) REFERENCES merchants(merchant_id)
);

CREATE TABLE card_transactions (
 card_transaction_id BIGINT PRIMARY KEY,
 account_id BIGINT NOT NULL,
 merchant_id INT NOT NULL,
 transaction_time DATETIME NOT NULL,
 card_type ENUM('Debit','Credit') NOT NULL,
 amount DECIMAL(14,2) NOT NULL,
 channel ENUM('POS','Online','Contactless') NOT NULL,
 city VARCHAR(80) NOT NULL,
 state VARCHAR(80) NOT NULL,
 status ENUM('Approved','Declined','Reversed') NOT NULL,
 FOREIGN KEY (account_id) REFERENCES accounts(account_id),
 FOREIGN KEY (merchant_id) REFERENCES merchants(merchant_id)
);

CREATE TABLE loans (
 loan_id INT PRIMARY KEY,
 customer_id INT NOT NULL,
 branch_id INT NOT NULL,
 loan_type ENUM('Home','Personal','Education','Vehicle','Business') NOT NULL,
 principal_amount DECIMAL(16,2) NOT NULL,
 interest_rate DECIMAL(5,2) NOT NULL,
 tenure_months INT NOT NULL,
 start_date DATE NOT NULL,
 loan_status ENUM('Active','Closed','Defaulted','Pending') NOT NULL,
 FOREIGN KEY (customer_id) REFERENCES customers(customer_id),
 FOREIGN KEY (branch_id) REFERENCES branches(branch_id)
);

CREATE TABLE loan_payments (
 payment_id BIGINT PRIMARY KEY,
 loan_id INT NOT NULL,
 payment_date DATE NOT NULL,
 due_amount DECIMAL(14,2) NOT NULL,
 paid_amount DECIMAL(14,2) NOT NULL,
 days_late INT NOT NULL,
 payment_status ENUM('Paid','Partial','Missed') NOT NULL,
 FOREIGN KEY (loan_id) REFERENCES loans(loan_id)
);

CREATE TABLE fraud_alerts (
 alert_id BIGINT PRIMARY KEY,
 transaction_id BIGINT NULL,
 card_transaction_id BIGINT NULL,
 alert_time DATETIME NOT NULL,
 fraud_type VARCHAR(120) NOT NULL,
 risk_score DECIMAL(5,2) NOT NULL,
 alert_status ENUM('Open','Investigating','Confirmed','False Positive','Closed') NOT NULL,
 FOREIGN KEY (transaction_id) REFERENCES transactions(transaction_id),
 FOREIGN KEY (card_transaction_id) REFERENCES card_transactions(card_transaction_id)
);

CREATE TABLE customer_complaints (
 complaint_id INT PRIMARY KEY,
 customer_id INT NOT NULL,
 complaint_date DATE NOT NULL,
 category VARCHAR(100) NOT NULL,
 priority ENUM('Low','Medium','High','Critical') NOT NULL,
 status ENUM('Open','In Progress','Resolved','Closed') NOT NULL,
 resolution_days INT NULL,
 FOREIGN KEY (customer_id) REFERENCES customers(customer_id)
);





